import{_ as t,o as a,c as d,a4 as r}from"./chunks/framework.BUqnS5H7.js";const f=JSON.parse('{"title":"Redis 概览与定位","description":"","frontmatter":{},"headers":[],"relativePath":"redis/01-data-model/chapter-01-overview.md","filePath":"redis/01-data-model/chapter-01-overview.md"}'),l={name:"redis/01-data-model/chapter-01-overview.md"};function i(s,e,c,o,n,h){return a(),d("div",null,[...e[0]||(e[0]=[r(`<h1 id="redis-概览与定位" tabindex="-1" data-src-line="1" data-src-file="redis/01-data-model/chapter-01-overview.md">Redis 概览与定位 <a class="header-anchor" href="#redis-概览与定位" aria-label="Permalink to &quot;Redis 概览与定位&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="redis/01-data-model/chapter-01-overview.md"><p data-src-line="3" data-src-file="redis/01-data-model/chapter-01-overview.md">Redis 是一个基于内存的数据结构服务器。理解它的定位，是正确使用它的前提——先看清它是什么、擅长什么、不该用来做什么，再进入细节。</p></blockquote><h2 id="_1-什么是-redis" tabindex="-1" data-src-line="5" data-src-file="redis/01-data-model/chapter-01-overview.md">1. 什么是 Redis <a class="header-anchor" href="#_1-什么是-redis" aria-label="Permalink to &quot;1. 什么是 Redis&quot;">​</a></h2><p data-src-line="7" data-src-file="redis/01-data-model/chapter-01-overview.md">Redis（Remote Dictionary Server）是一个开源的键值对存储系统，数据保存在内存中，读写速度远超基于磁盘的数据库。它的本质是一个<strong>数据结构服务器</strong>：value 不只是普通字符串，而可以是 String、Hash、List、Set、ZSet 等多种数据结构，并针对每种结构提供原子操作命令。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>key  →  value（value 可以是多种数据结构）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;user:123&quot;        →  &quot;{name:&#39;张三&#39;, age:25}&quot;     String</span></span>
<span class="line"><span>&quot;user:123:info&quot;   →  {name, age, email}          Hash</span></span>
<span class="line"><span>&quot;news:list&quot;       →  [文章3, 文章2, 文章1]         List</span></span>
<span class="line"><span>&quot;user:123:tags&quot;   →  {Java, 后端, 分布式}          Set</span></span>
<span class="line"><span>&quot;leaderboard&quot;     →  {张三:100, 李四:200}          ZSet</span></span></code></pre></div><p data-src-line="19" data-src-file="redis/01-data-model/chapter-01-overview.md">Redis 官方对它的定位是「内存数据结构服务器」，广泛用作缓存、消息队列、分布式锁、排行榜等。它常被放在 MySQL 这类持久化数据库之前，利用内存的高速访问缓解数据库压力。</p><h2 id="_2-诞生背景与作者" tabindex="-1" data-src-line="21" data-src-file="redis/01-data-model/chapter-01-overview.md">2. 诞生背景与作者 <a class="header-anchor" href="#_2-诞生背景与作者" aria-label="Permalink to &quot;2. 诞生背景与作者&quot;">​</a></h2><p data-src-line="23" data-src-file="redis/01-data-model/chapter-01-overview.md">Redis 的起点是一个真实的生产瓶颈，而非预先规划的产品。</p><h3 id="_2-1-起因-lloogg-的性能瓶颈" tabindex="-1" data-src-line="25" data-src-file="redis/01-data-model/chapter-01-overview.md">2.1 起因：LLOOGG 的性能瓶颈 <a class="header-anchor" href="#_2-1-起因-lloogg-的性能瓶颈" aria-label="Permalink to &quot;2.1 起因：LLOOGG 的性能瓶颈&quot;">​</a></h3><p data-src-line="27" data-src-file="redis/01-data-model/chapter-01-overview.md">2009 年，意大利西西里岛的工程师 Salvatore Sanfilippo（网名 antirez）在为自己的创业项目 <strong>LLOOGG</strong> 做实时网站访问统计。LLOOGG 为每个接入的网站维护一个「最新 N 条访问记录」列表：新访问进来时把记录推入列表尾部，列表超长时再把最早的记录弹出。</p><p data-src-line="29" data-src-file="redis/01-data-model/chapter-01-overview.md">这套「推入 + 弹出」操作当时跑在 MySQL 上。MySQL 每次推入、弹出都要读写硬盘，而 LLOOGG 的用户越多、要维护的列表就越多，性能最终受制于硬盘 I/O。当时 LLOOGG 没有盈利模式，antirez 不愿直接升级服务器，于是决定自己写一个内存数据库原型：以列表为基本类型，对列表两端做 O(1) 的推入和弹出，数据放内存而非硬盘。</p><h3 id="_2-2-从-tcl-原型到-c-实现" tabindex="-1" data-src-line="31" data-src-file="redis/01-data-model/chapter-01-overview.md">2.2 从 Tcl 原型到 C 实现 <a class="header-anchor" href="#_2-2-从-tcl-原型到-c-实现" aria-label="Permalink to &quot;2.2 从 Tcl 原型到 C 实现&quot;">​</a></h3><p data-src-line="33" data-src-file="redis/01-data-model/chapter-01-overview.md">antirez 先用 Tcl 写了一个约 300 行的原型验证想法，随后用 C 重写，并加上基于子进程的持久化——这就是后来 RDB 快照的思路。2009 年 2 月，项目以 <strong>Redis</strong>（REmote DIctionary Server，远程字典服务）之名开源，并在 Hacker News 上发布。</p><blockquote data-src-line="35" data-src-file="redis/01-data-model/chapter-01-overview.md"><p data-src-line="35" data-src-file="redis/01-data-model/chapter-01-overview.md">Redis 默认端口 6379 并非随意挑选：在老式电话键盘上，6379 对应「MERZ」，即 antirez 创业公司 Merzia 的前四个字母。</p></blockquote><h3 id="_2-3-谁在主导-从一人维护到公司赞助" tabindex="-1" data-src-line="37" data-src-file="redis/01-data-model/chapter-01-overview.md">2.3 谁在主导：从一人维护到公司赞助 <a class="header-anchor" href="#_2-3-谁在主导-从一人维护到公司赞助" aria-label="Permalink to &quot;2.3 谁在主导：从一人维护到公司赞助&quot;">​</a></h3><p data-src-line="39" data-src-file="redis/01-data-model/chapter-01-overview.md">Redis 前 11 年基本由 antirez 一人主导，他是事实上的 BDFL（终身仁慈独裁者）——功能的取舍、bug 的修复方式、设计的权衡都由他最终拍板。另一位核心贡献者 Pieter Noordhuis 也深度参与开发。</p><p data-src-line="41" data-src-file="redis/01-data-model/chapter-01-overview.md">随着项目流行，Redis 的开发获得了一系列公司赞助：</p><table tabindex="0"><thead data-src-line="43" data-src-file="redis/01-data-model/chapter-01-overview.md"><tr data-src-line="43" data-src-file="redis/01-data-model/chapter-01-overview.md"><th style="text-align:left;">时间</th><th style="text-align:left;">赞助方</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="45" data-src-file="redis/01-data-model/chapter-01-overview.md"><tr data-src-line="45" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">2010 ~ 2013</td><td style="text-align:left;">VMware</td><td style="text-align:left;">antirez 与 Pieter Noordhuis 先后加入，全职开发</td></tr><tr data-src-line="46" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">2013 ~ 2015</td><td style="text-align:left;">Pivotal</td><td style="text-align:left;">VMware 分拆出的公司继续赞助</td></tr><tr data-src-line="47" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">2015 起</td><td style="text-align:left;">Redis Labs（后更名 Redis）</td><td style="text-align:left;">商业化公司接手赞助</td></tr></tbody></table><p data-src-line="49" data-src-file="redis/01-data-model/chapter-01-overview.md">早期采用者包括 GitHub（用它做 Resque 队列）、Instagram（存储数亿个简单键值对）、Twitter（trending topics 等），Redis 由此在社区快速传播。</p><h2 id="_3-核心特性" tabindex="-1" data-src-line="51" data-src-file="redis/01-data-model/chapter-01-overview.md">3. 核心特性 <a class="header-anchor" href="#_3-核心特性" aria-label="Permalink to &quot;3. 核心特性&quot;">​</a></h2><table tabindex="0"><thead data-src-line="53" data-src-file="redis/01-data-model/chapter-01-overview.md"><tr data-src-line="53" data-src-file="redis/01-data-model/chapter-01-overview.md"><th style="text-align:left;">特性</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="55" data-src-file="redis/01-data-model/chapter-01-overview.md"><tr data-src-line="55" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">快</td><td style="text-align:left;">纯内存操作，单机 QPS 轻松突破 10 万</td></tr><tr data-src-line="56" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">数据结构丰富</td><td style="text-align:left;">5 种基础类型 + 4 种高级类型，覆盖绝大多数业务场景</td></tr><tr data-src-line="57" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">原子操作</td><td style="text-align:left;">命令由单线程执行，单条命令天然原子，无并发竞争</td></tr><tr data-src-line="58" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">持久化</td><td style="text-align:left;">提供 RDB 快照与 AOF 日志两种持久化方式</td></tr><tr data-src-line="59" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">高可用</td><td style="text-align:left;">主从复制、哨兵、集群三种方案逐级演进</td></tr><tr data-src-line="60" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">功能扩展</td><td style="text-align:left;">支持事务、Lua 脚本、发布订阅、Pipeline 等</td></tr></tbody></table><h2 id="_4-版本演进与发版节奏" tabindex="-1" data-src-line="62" data-src-file="redis/01-data-model/chapter-01-overview.md">4. 版本演进与发版节奏 <a class="header-anchor" href="#_4-版本演进与发版节奏" aria-label="Permalink to &quot;4. 版本演进与发版节奏&quot;">​</a></h2><h3 id="_4-1-发版节奏" tabindex="-1" data-src-line="64" data-src-file="redis/01-data-model/chapter-01-overview.md">4.1 发版节奏 <a class="header-anchor" href="#_4-1-发版节奏" aria-label="Permalink to &quot;4.1 发版节奏&quot;">​</a></h3><p data-src-line="66" data-src-file="redis/01-data-model/chapter-01-overview.md">Redis 计划每年发布一个主版本，每个主版本约半年后跟一个次版本。最新的稳定版本获得完整支持，此前的次版本和上一个主版本仅做维护性修补（关键 bug 与安全漏洞）。</p><table tabindex="0"><thead data-src-line="68" data-src-file="redis/01-data-model/chapter-01-overview.md"><tr data-src-line="68" data-src-file="redis/01-data-model/chapter-01-overview.md"><th style="text-align:left;">版本</th><th style="text-align:left;">发布时间</th><th style="text-align:left;">标志性变化</th></tr></thead><tbody data-src-line="70" data-src-file="redis/01-data-model/chapter-01-overview.md"><tr data-src-line="70" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">1.0</td><td style="text-align:left;">2009</td><td style="text-align:left;">首次发布，基础数据类型</td></tr><tr data-src-line="71" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">2.6</td><td style="text-align:left;">2012</td><td style="text-align:left;">Lua 脚本</td></tr><tr data-src-line="72" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">3.0</td><td style="text-align:left;">2015</td><td style="text-align:left;">Redis Cluster 分片</td></tr><tr data-src-line="73" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">4.0</td><td style="text-align:left;">2017</td><td style="text-align:left;">模块系统、混合持久化</td></tr><tr data-src-line="74" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">5.0</td><td style="text-align:left;">2018</td><td style="text-align:left;">Streams 数据类型</td></tr><tr data-src-line="75" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">6.0</td><td style="text-align:left;">2020</td><td style="text-align:left;">RESP3、ACL、多线程 I/O</td></tr><tr data-src-line="76" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">7.0</td><td style="text-align:left;">2022</td><td style="text-align:left;">Functions、Multi-part AOF</td></tr><tr data-src-line="77" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">8.0</td><td style="text-align:left;">2025</td><td style="text-align:left;">模块并入核心、Vector Set</td></tr></tbody></table><p data-src-line="79" data-src-file="redis/01-data-model/chapter-01-overview.md">本书聚焦 <strong>Redis 6.0 ~ 7.2</strong>。6.0 起支持多线程网络 IO（命令执行仍单线程），7.0 引入 Functions 和 MP-AOF，7.2 彻底用 listpack 替代 ziplist。自 7.4 起 Redis 切换为 RSALv2 + SSPLv1 双协议，社区出现 Valkey 等开源分支。</p><h3 id="_4-2-版本与许可证" tabindex="-1" data-src-line="81" data-src-file="redis/01-data-model/chapter-01-overview.md">4.2 版本与许可证 <a class="header-anchor" href="#_4-2-版本与许可证" aria-label="Permalink to &quot;4.2 版本与许可证&quot;">​</a></h3><p data-src-line="83" data-src-file="redis/01-data-model/chapter-01-overview.md">2024 年起 Redis 的许可证经历了一次影响深远的变化，不同版本范围对应不同许可证：</p><table tabindex="0"><thead data-src-line="85" data-src-file="redis/01-data-model/chapter-01-overview.md"><tr data-src-line="85" data-src-file="redis/01-data-model/chapter-01-overview.md"><th style="text-align:left;">版本范围</th><th style="text-align:left;">许可证</th></tr></thead><tbody data-src-line="87" data-src-file="redis/01-data-model/chapter-01-overview.md"><tr data-src-line="87" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">≤ 7.2</td><td style="text-align:left;">BSD-3-Clause</td></tr><tr data-src-line="88" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">7.4 ~ 7.8</td><td style="text-align:left;">RSALv2 / SSPLv1 二选一</td></tr><tr data-src-line="89" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">≥ 8.0</td><td style="text-align:left;">RSALv2 / SSPLv1 / AGPLv3 三选一</td></tr></tbody></table><h2 id="_5-项目治理与现状" tabindex="-1" data-src-line="91" data-src-file="redis/01-data-model/chapter-01-overview.md">5. 项目治理与现状 <a class="header-anchor" href="#_5-项目治理与现状" aria-label="Permalink to &quot;5. 项目治理与现状&quot;">​</a></h2><h3 id="_5-1-antirez-卸任" tabindex="-1" data-src-line="93" data-src-file="redis/01-data-model/chapter-01-overview.md">5.1 antirez 卸任 <a class="header-anchor" href="#_5-1-antirez-卸任" aria-label="Permalink to &quot;5.1 antirez 卸任&quot;">​</a></h3><p data-src-line="95" data-src-file="redis/01-data-model/chapter-01-overview.md">2020 年 6 月，维护 Redis 11 年的 antirez 宣布卸任维护者。他在博客《The end of the Redis adventure》里给出的理由是：他更想写代码、做创造性的工作，而不是陷入一个大型项目的日常维护。卸任后他仍是社区成员和 Redis 技术顾问委员会成员。</p><h3 id="_5-2-从-bdfl-到社区驱动-core-team" tabindex="-1" data-src-line="97" data-src-file="redis/01-data-model/chapter-01-overview.md">5.2 从 BDFL 到社区驱动 Core Team <a class="header-anchor" href="#_5-2-从-bdfl-到社区驱动-core-team" aria-label="Permalink to &quot;5.2 从 BDFL 到社区驱动 Core Team&quot;">​</a></h3><p data-src-line="99" data-src-file="redis/01-data-model/chapter-01-overview.md">antirez 卸任后，Redis 的规模已无法继续用「一人拍板」的 BDFL 模式运转。接手的两位长期贡献者 Yossi Gottlieb 和 Oran Agra 提出了一套「轻治理」模式：由一个小型 Core Team 根据成员的参与度和贡献选出，共同决策，取代 BDFL。</p><h3 id="_5-3-现在的维护者是谁" tabindex="-1" data-src-line="101" data-src-file="redis/01-data-model/chapter-01-overview.md">5.3 现在的维护者是谁 <a class="header-anchor" href="#_5-3-现在的维护者是谁" aria-label="Permalink to &quot;5.3 现在的维护者是谁&quot;">​</a></h3><p data-src-line="103" data-src-file="redis/01-data-model/chapter-01-overview.md">目前 Redis 的开源项目由 <strong>Redis 公司</strong>（原名 Redis Labs，2021 年更名）主导。这家公司 2011 年以 Garantia Data 之名成立，专做 Redis 相关的商业服务。Core Team 成员主要来自 Redis 公司，也有来自云厂商的贡献者。</p><p data-src-line="105" data-src-file="redis/01-data-model/chapter-01-overview.md">2024 年 12 月，antirez 以「Redis 布道者」身份回归 Redis 公司，不再负责日常维护，转向技术布道和新特性设计（如 Vector Set）。</p><h2 id="_6-适用场景与反模式" tabindex="-1" data-src-line="107" data-src-file="redis/01-data-model/chapter-01-overview.md">6. 适用场景与反模式 <a class="header-anchor" href="#_6-适用场景与反模式" aria-label="Permalink to &quot;6. 适用场景与反模式&quot;">​</a></h2><p data-src-line="109" data-src-file="redis/01-data-model/chapter-01-overview.md"><strong>适合的场景</strong>：</p><table tabindex="0"><thead data-src-line="111" data-src-file="redis/01-data-model/chapter-01-overview.md"><tr data-src-line="111" data-src-file="redis/01-data-model/chapter-01-overview.md"><th style="text-align:left;">场景</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="113" data-src-file="redis/01-data-model/chapter-01-overview.md"><tr data-src-line="113" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">缓存</td><td style="text-align:left;">热点数据缓存，缓解数据库压力</td></tr><tr data-src-line="114" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">排行榜</td><td style="text-align:left;">ZSet 按 score 排序，天然适配</td></tr><tr data-src-line="115" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">计数器</td><td style="text-align:left;">INCR 原子自增，无并发问题</td></tr><tr data-src-line="116" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">分布式锁</td><td style="text-align:left;">SET NX PX 原子加锁</td></tr><tr data-src-line="117" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">消息队列</td><td style="text-align:left;">List 阻塞弹出、Stream 消费者组</td></tr><tr data-src-line="118" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">会话存储</td><td style="text-align:left;">共享 Session，TTL 自动过期</td></tr></tbody></table><p data-src-line="120" data-src-file="redis/01-data-model/chapter-01-overview.md"><strong>反模式</strong>（不该把 Redis 当作）：</p><table tabindex="0"><thead data-src-line="122" data-src-file="redis/01-data-model/chapter-01-overview.md"><tr data-src-line="122" data-src-file="redis/01-data-model/chapter-01-overview.md"><th style="text-align:left;">反模式</th><th style="text-align:left;">原因</th></tr></thead><tbody data-src-line="124" data-src-file="redis/01-data-model/chapter-01-overview.md"><tr data-src-line="124" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">主数据库</td><td style="text-align:left;">内存容量有限，数据量大时成本高</td></tr><tr data-src-line="125" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">强一致存储</td><td style="text-align:left;">主从复制异步，可能丢少量数据</td></tr><tr data-src-line="126" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">大文件存储</td><td style="text-align:left;">大 Key 阻塞命令执行、占用带宽</td></tr><tr data-src-line="127" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">关系型查询</td><td style="text-align:left;">无 SQL、无复杂关联查询能力</td></tr></tbody></table><h2 id="_7-与-memcached-对比" tabindex="-1" data-src-line="129" data-src-file="redis/01-data-model/chapter-01-overview.md">7. 与 Memcached 对比 <a class="header-anchor" href="#_7-与-memcached-对比" aria-label="Permalink to &quot;7. 与 Memcached 对比&quot;">​</a></h2><p data-src-line="131" data-src-file="redis/01-data-model/chapter-01-overview.md">Memcached 是另一款常见的内存缓存，二者常被放在一起比较：</p><table tabindex="0"><thead data-src-line="133" data-src-file="redis/01-data-model/chapter-01-overview.md"><tr data-src-line="133" data-src-file="redis/01-data-model/chapter-01-overview.md"><th style="text-align:left;">对比项</th><th style="text-align:left;">Redis</th><th style="text-align:left;">Memcached</th></tr></thead><tbody data-src-line="135" data-src-file="redis/01-data-model/chapter-01-overview.md"><tr data-src-line="135" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">数据类型</td><td style="text-align:left;">5 种基础 + 4 种高级</td><td style="text-align:left;">仅 String</td></tr><tr data-src-line="136" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">持久化</td><td style="text-align:left;">支持 RDB/AOF</td><td style="text-align:left;">不支持</td></tr><tr data-src-line="137" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">集群</td><td style="text-align:left;">原生支持主从/哨兵/集群</td><td style="text-align:left;">需客户端实现分片</td></tr><tr data-src-line="138" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">线程模型</td><td style="text-align:left;">单线程 + IO 多路复用</td><td style="text-align:left;">多线程</td></tr><tr data-src-line="139" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">功能</td><td style="text-align:left;">事务、Lua、订阅、Pipeline</td><td style="text-align:left;">无</td></tr></tbody></table><p data-src-line="141" data-src-file="redis/01-data-model/chapter-01-overview.md">选择标准：需要丰富数据结构、持久化、高可用时选 Redis；仅做简单 KV 缓存、追求极致简洁时 Memcached 才进入考虑范围。</p><h3 id="_7-1-性能基准对比" tabindex="-1" data-src-line="143" data-src-file="redis/01-data-model/chapter-01-overview.md">7.1 性能基准对比 <a class="header-anchor" href="#_7-1-性能基准对比" aria-label="Permalink to &quot;7.1 性能基准对比&quot;">​</a></h3><p data-src-line="145" data-src-file="redis/01-data-model/chapter-01-overview.md">Redis 自带 <code>redis-benchmark</code> 工具，模拟 N 个客户端并发发送 M 个请求。官方文档给出的参考值：50 并发、10 万请求、3 字节负载下，<code>SET</code> 约 18 万次/秒、<code>LPUSH</code> 约 18.8 万次/秒；开启 pipelining（<code>-P 16</code>）后可达 <code>SET</code> 153 万次/秒、<code>GET</code> 181 万次/秒。</p><p data-src-line="147" data-src-file="redis/01-data-model/chapter-01-overview.md">与 Memcached 的性能差异随硬件、负载、版本而变，但有两点相对稳定：</p><ol data-src-line="149" data-src-file="redis/01-data-model/chapter-01-overview.md"><li data-src-line="149" data-src-file="redis/01-data-model/chapter-01-overview.md"><strong>简单 GET/SET、单命令场景</strong>：Memcached 的多线程架构在纯键值读写上占优，吞吐量可高出约 20% ~ 40%。</li><li data-src-line="150" data-src-file="redis/01-data-model/chapter-01-overview.md"><strong>pipelining、复杂结构、写密集场景</strong>：Redis 凭借协议与数据结构优势反超。</li></ol><table tabindex="0"><thead data-src-line="152" data-src-file="redis/01-data-model/chapter-01-overview.md"><tr data-src-line="152" data-src-file="redis/01-data-model/chapter-01-overview.md"><th style="text-align:left;">场景</th><th style="text-align:left;">Redis</th><th style="text-align:left;">Memcached</th></tr></thead><tbody data-src-line="154" data-src-file="redis/01-data-model/chapter-01-overview.md"><tr data-src-line="154" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">简单 SET（256B）</td><td style="text-align:left;">约 15 万 ops/s</td><td style="text-align:left;">约 20 万 ops/s</td></tr><tr data-src-line="155" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">简单 GET（256B）</td><td style="text-align:left;">约 18 万 ops/s</td><td style="text-align:left;">约 25 万 ops/s</td></tr><tr data-src-line="156" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">pipelined GET ×10</td><td style="text-align:left;">约 80 万 ops/s</td><td style="text-align:left;">约 75 万 ops/s</td></tr><tr data-src-line="157" data-src-file="redis/01-data-model/chapter-01-overview.md"><td style="text-align:left;">p50 延迟（GET）</td><td style="text-align:left;">约 0.12 ms</td><td style="text-align:left;">约 0.09 ms</td></tr></tbody></table><blockquote data-src-line="159" data-src-file="redis/01-data-model/chapter-01-overview.md"><p data-src-line="159" data-src-file="redis/01-data-model/chapter-01-overview.md">📌 性能数据高度依赖硬件、网络、版本与测试方法。上表取自第三方横评的综合量级，仅用于建立直觉，不构成绝对结论；严谨选型应基于真实负载用 <code>redis-benchmark</code> 复测。</p></blockquote><h2 id="_8-参考资料" tabindex="-1" data-src-line="161" data-src-file="redis/01-data-model/chapter-01-overview.md">8. 参考资料 <a class="header-anchor" href="#_8-参考资料" aria-label="Permalink to &quot;8. 参考资料&quot;">​</a></h2><ul data-src-line="163" data-src-file="redis/01-data-model/chapter-01-overview.md"><li data-src-line="163" data-src-file="redis/01-data-model/chapter-01-overview.md">Redis 官方基准测试：<a href="https://redis.io/docs/latest/operate/oss_and_stack/management/optimization/benchmarks/" target="_blank" rel="noreferrer">How fast is Redis?</a></li><li data-src-line="164" data-src-file="redis/01-data-model/chapter-01-overview.md">Redis 官方博客：<a href="https://redis.io/blog/new-governance-for-redis" target="_blank" rel="noreferrer">New Governance for Redis</a></li><li data-src-line="165" data-src-file="redis/01-data-model/chapter-01-overview.md">Redis 官方博客：<a href="https://redis.io/blog/thank-you-salvatore-sanfilippo" target="_blank" rel="noreferrer">Thank You, Salvatore Sanfilippo</a></li><li data-src-line="166" data-src-file="redis/01-data-model/chapter-01-overview.md">Wikipedia：<a href="https://en.wikipedia.org/wiki/Redis" target="_blank" rel="noreferrer">Redis</a></li><li data-src-line="167" data-src-file="redis/01-data-model/chapter-01-overview.md">endoflife.date：<a href="https://endoflife.date/redis" target="_blank" rel="noreferrer">Redis 版本与支持策略</a></li><li data-src-line="168" data-src-file="redis/01-data-model/chapter-01-overview.md">The Register：<a href="https://www.theregister.com/2020/06/30/redis_creator_antirez_quits" target="_blank" rel="noreferrer">Database maestro Antirez says arrivederci to Redis</a></li></ul>`,54)])])}const v=t(l,[["render",i]]);export{f as __pageData,v as default};
